  1→//! AES-256-GCM encryption/decryption.
  2→//!
  3→//! Sealed format: IV (12 bytes) || Ciphertext || Auth Tag (16 bytes)
  4→//! This matches the TypeScript `sealAesGcm` output exactly.
  5→
  6→use aes_gcm::{
  7→    aead::{Aead, KeyInit},
  8→    Aes256Gcm, Nonce,
  9→};
 10→use thiserror::Error;
 11→
 12→use super::utils::generate_iv;
 13→
 14→/// AES-256-GCM key size in bytes (256 bits).
 15→pub const AES_KEY_SIZE: usize = 32;
 16→
 17→/// AES-GCM IV size in bytes (96 bits).
 18→pub const AES_IV_SIZE: usize = 12;
 19→
 20→/// AES-GCM authentication tag size in bytes (128 bits).
 21→pub const AES_TAG_SIZE: usize = 16;
 22→
 23→/// Minimum sealed data size: IV + auth tag (empty plaintext).
 24→const MIN_SEALED_SIZE: usize = AES_IV_SIZE + AES_TAG_SIZE;
 25→
 26→#[derive(Debug, Error)]
 27→pub enum AesError {
 28→    #[error("Encryption failed")]
 29→    EncryptionFailed,
 30→    #[error("Decryption failed")]
 31→    DecryptionFailed,
 32→    #[error("Invalid key size")]
 33→    InvalidKeySize,
 34→    #[error("Invalid IV size")]
 35→    InvalidIvSize,
 36→}
 37→
 38→/// Encrypt data using AES-256-GCM.
 39→///
 40→/// Returns ciphertext with 16-byte auth tag appended (same as Web Crypto API).
 41→pub fn encrypt_aes_gcm(
 42→    plaintext: &[u8],
 43→    key: &[u8; 32],
 44→    iv: &[u8; 12],
 45→) -> Result<Vec<u8>, AesError> {
 46→    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| AesError::EncryptionFailed)?;
 47→    let nonce = Nonce::from_slice(iv);
 48→
 49→    cipher
 50→        .encrypt(nonce, plaintext)
 51→        .map_err(|_| AesError::EncryptionFailed)
 52→}
 53→
 54→/// Decrypt data using AES-256-GCM.
 55→///
 56→/// Expects ciphertext with 16-byte auth tag appended.
 57→pub fn decrypt_aes_gcm(
 58→    ciphertext: &[u8],
 59→    key: &[u8; 32],
 60→    iv: &[u8; 12],
 61→) -> Result<Vec<u8>, AesError> {
 62→    let cipher = Aes256Gcm::new_from_slice(key).map_err(|_| AesError::DecryptionFailed)?;
 63→    let nonce = Nonce::from_slice(iv);
 64→
 65→    cipher
 66→        .decrypt(nonce, ciphertext)
 67→        .map_err(|_| AesError::DecryptionFailed)
 68→}
 69→
 70→/// Seal data using AES-256-GCM with automatic IV generation.
 71→///
 72→/// Returns: IV (12 bytes) || Ciphertext || Auth Tag (16 bytes)
 73→/// This format matches the TypeScript `sealAesGcm` exactly.
 74→pub fn seal_aes_gcm(plaintext: &[u8], key: &[u8; 32]) -> Result<Vec<u8>, AesError> {
 75→    let iv = generate_iv();
 76→    let ciphertext = encrypt_aes_gcm(plaintext, key, &iv)?;
 77→
 78→    // IV || ciphertext (which already includes the tag)
 79→    let mut sealed = Vec::with_capacity(AES_IV_SIZE + ciphertext.len());
 80→    sealed.extend_from_slice(&iv);
 81→    sealed.extend_from_slice(&ciphertext);
 82→    Ok(sealed)
 83→}
 84→
 85→/// Unseal data encrypted with `seal_aes_gcm`.
 86→///
 87→/// Extracts IV from first 12 bytes, decrypts remainder.
 88→pub fn unseal_aes_gcm(sealed: &[u8], key: &[u8; 32]) -> Result<Vec<u8>, AesError> {
 89→    if sealed.len() < MIN_SEALED_SIZE {
 90→        return Err(AesError::DecryptionFailed);
 91→    }
 92→
 93→    let iv: [u8; 12] = sealed[..AES_IV_SIZE]
 94→        .try_into()
 95→        .map_err(|_| AesError::DecryptionFailed)?;
 96→    let ciphertext = &sealed[AES_IV_SIZE..];
 97→
 98→    decrypt_aes_gcm(ciphertext, key, &iv)
 99→}
