 1→//! ECIES key wrapping using secp256k1.
 2→//!
 3→//! Uses the `ecies` Rust crate which is cross-compatible with the `eciesjs` npm package
 4→//! (same author: ecies/rs and ecies/js). Format: ephemeral_pubkey(65) || nonce(16) || tag(16) || ciphertext.
 5→
 6→use thiserror::Error;
 7→
 8→/// secp256k1 uncompressed public key size in bytes (04 prefix + x + y coordinates).
 9→pub const SECP256K1_PUBLIC_KEY_SIZE: usize = 65;
10→
11→/// secp256k1 private key size in bytes.
12→pub const SECP256K1_PRIVATE_KEY_SIZE: usize = 32;
13→
14→/// ECIES minimum ciphertext size: ephemeral pubkey (65) + auth tag (16).
15→pub const ECIES_MIN_CIPHERTEXT_SIZE: usize = SECP256K1_PUBLIC_KEY_SIZE + 16;
16→
17→#[derive(Debug, Error)]
18→pub enum EciesError {
19→    #[error("Key wrapping failed")]
20→    WrappingFailed,
21→    #[error("Key unwrapping failed")]
22→    UnwrappingFailed,
23→    #[error("Invalid public key size")]
24→    InvalidPublicKeySize,
25→    #[error("Invalid public key format")]
26→    InvalidPublicKeyFormat,
27→    #[error("Invalid private key size")]
28→    InvalidPrivateKeySize,
29→}
30→
31→/// Wrap (encrypt) data using ECIES with secp256k1.
32→///
33→/// The `ecies` Rust crate and `eciesjs` npm package produce compatible output.
34→pub fn wrap_key(data: &[u8], recipient_public_key: &[u8]) -> Result<Vec<u8>, EciesError> {
35→    // Validate public key size (uncompressed secp256k1)
36→    if recipient_public_key.len() != SECP256K1_PUBLIC_KEY_SIZE {
37→        return Err(EciesError::InvalidPublicKeySize);
38→    }
39→
40→    // Validate uncompressed public key prefix (0x04)
41→    if recipient_public_key[0] != 0x04 {
42→        return Err(EciesError::InvalidPublicKeyFormat);
43→    }
44→
45→    ecies::encrypt(recipient_public_key, data).map_err(|_| EciesError::WrappingFailed)
46→}
47→
48→/// Unwrap (decrypt) data using ECIES with secp256k1.
49→pub fn unwrap_key(wrapped: &[u8], private_key: &[u8]) -> Result<Vec<u8>, EciesError> {
50→    // Validate private key size
51→    if private_key.len() != SECP256K1_PRIVATE_KEY_SIZE {
52→        return Err(EciesError::InvalidPrivateKeySize);
53→    }
54→
55→    // Validate minimum ciphertext size
56→    if wrapped.len() < ECIES_MIN_CIPHERTEXT_SIZE {
57→        return Err(EciesError::UnwrappingFailed);
58→    }
59→
60→    ecies::decrypt(private_key, wrapped).map_err(|_| EciesError::UnwrappingFailed)
61→}
62→

  1→//! Vault blob v2 format: binary envelope for root folder IPFS blobs.
  2→//!
  3→//! Format: 0x02 | uint16_BE(key_len) | ECIES_encrypted_key | AES_GCM_metadata_json
  4→//!
  5→//! v1 blobs are plain JSON: {"iv":"...","data":"..."}
  6→//! v2 blobs prepend the ECIES-wrapped rootFolderKey before the metadata JSON.
  7→
  8→/// Version byte for v2 format.
  9→pub const BLOB_V2_VERSION: u8 = 0x02;
 10→
 11→/// Detect whether a vault blob is v1 (JSON) or v2 (binary envelope).
 12→///
 13→/// v1 blobs start with 0x7B ('{' -- JSON). v2 blobs start with 0x02.
 14→pub fn detect_blob_version(blob: &[u8]) -> u8 {
 15→    if !blob.is_empty() && blob[0] == BLOB_V2_VERSION {
 16→        2
 17→    } else {
 18→        1
 19→    }
 20→}
 21→
 22→/// Serialize a vault blob v2.
 23→///
 24→/// Produces: `0x02 | uint16_BE(key_len) | encrypted_root_folder_key | encrypted_metadata_json`
 25→pub fn serialize_vault_blob_v2(
 26→    encrypted_root_folder_key: &[u8],
 27→    encrypted_metadata_json: &[u8],
 28→) -> Result<Vec<u8>, String> {
 29→    if encrypted_root_folder_key.is_empty() {
 30→        return Err("Encrypted key must not be empty for v2 blob".into());
 31→    }
 32→    if encrypted_root_folder_key.len() > u16::MAX as usize {
 33→        return Err(format!(
 34→            "Encrypted key too long for v2 blob ({} bytes, max {})",
 35→            encrypted_root_folder_key.len(),
 36→            u16::MAX
 37→        ));
 38→    }
 39→    let key_len = encrypted_root_folder_key.len() as u16;
 40→    let mut result =
 41→        Vec::with_capacity(3 + encrypted_root_folder_key.len() + encrypted_metadata_json.len());
 42→    result.push(BLOB_V2_VERSION);
 43→    result.push((key_len >> 8) as u8);
 44→    result.push((key_len & 0xff) as u8);
 45→    result.extend_from_slice(encrypted_root_folder_key);
 46→    result.extend_from_slice(encrypted_metadata_json);
 47→    Ok(result)
 48→}
 49→
 50→/// Deserialize a vault blob v2 into (encrypted_key, encrypted_metadata_json).
 51→///
 52→/// Returns borrowed slices into the original blob for zero-copy parsing.
 53→pub fn deserialize_vault_blob_v2(blob: &[u8]) -> Result<(&[u8], &[u8]), String> {
 54→    if blob.len() < 3 {
 55→        return Err(format!(
 56→            "Vault blob too short for v2 header (need at least 3 bytes, have {})",
 57→            blob.len()
 58→        ));
 59→    }
 60→    if blob[0] != BLOB_V2_VERSION {
 61→        return Err("Not a v2 vault blob".into());
 62→    }
 63→    let key_len = ((blob[1] as usize) << 8) | (blob[2] as usize);
 64→    if key_len == 0 {
 65→        return Err("Invalid v2 blob: encrypted key length must be > 0".into());
 66→    }
 67→    if blob.len() < 3 + key_len {
 68→        return Err(format!(
 69→            "Vault blob too short for key (expected {} bytes, have {})",
 70→            key_len,
 71→            blob.len() - 3
 72→        ));
 73→    }
 74→    Ok((&blob[3..3 + key_len], &blob[3 + key_len..]))
 75→}
