 59→/// Timeout for network I/O in filesystem callbacks to prevent blocking the mount thread.
 60→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 61→const NETWORK_TIMEOUT: Duration = Duration::from_secs(10);
 62→
 63→/// Run an async future with a timeout on the tokio runtime.
 64→/// Prevents filesystem thread hangs from indefinite network I/O.
 65→#[cfg(any(feature = "fuse", feature = "winfsp"))]
 66→fn block_with_timeout<F, T>(rt: &tokio::runtime::Handle, fut: F) -> Result<T, String>
 67→where
 68→    F: std::future::Future<Output = Result<T, String>>,
 69→{
 70→    rt.block_on(async {
 71→        match tokio::time::timeout(NETWORK_TIMEOUT, fut).await {
 72→            Ok(result) => result,
 73→            Err(_) => Err("Operation timed out".to_string()),
 74→        }
 75→    })
 76→}
