 1→//! Background sync daemon command.
 2→
 3→use std::sync::Arc;
 4→
 5→use tauri::{Manager, State};
 6→
 7→use crate::state::AppState;
 8→
 9→/// Start the background sync daemon.
10→///
11→/// Called from the webview after successful auth + mount. Creates the sync channel,
12→/// stores the sender in AppState for the tray menu, and spawns the daemon.
13→#[tauri::command]
14→pub async fn start_sync_daemon(
15→    app: tauri::AppHandle,
16→    state: State<'_, AppState>,
17→) -> Result<(), String> {
18→    log::info!("Starting background sync daemon");
19→
20→    let (tx, rx) = tokio::sync::mpsc::channel::<()>(1);
21→
22→    // Store the sender in AppState so the tray "Sync Now" button can trigger syncs
23→    if let Ok(mut guard) = state.sync_trigger.write() {
24→        *guard = Some(tx);
25→    }
26→
27→    // Extract shared references the daemon needs from AppState.
28→    // AppState fields are RwLock which we wrap in Arc for shared ownership
29→    // between the daemon task and the Tauri-managed state.
30→    //
31→    // We use the AppHandle to get the managed state which is already Arc-wrapped by Tauri.
32→    // The daemon reads root_ipns_name and is_authenticated via the app handle's state.
33→    let api = state.api.clone();
34→    let app_handle = app.clone();
35→
36→    // Get the root IPNS name -- daemon needs to read it periodically
37→    let root_ipns_name = state.root_ipns_name.read().await.clone();
38→
39→    // Clone values for the daemon's owned copies
40→    let root_ipns_name_lock = Arc::new(tokio::sync::RwLock::new(root_ipns_name));
41→    let is_authenticated_lock = Arc::new(tokio::sync::RwLock::new(
42→        *state.is_authenticated.read().await,
43→    ));
44→
45→    // Spawn sync state bridge: periodically sync auth/ipns state from AppState to daemon
46→    let bridge_app = app.clone();
47→    let bridge_root = root_ipns_name_lock.clone();
48→    let bridge_auth = is_authenticated_lock.clone();
49→    tokio::spawn(async move {
50→        loop {
51→            tokio::time::sleep(std::time::Duration::from_secs(5)).await;
52→            let state = bridge_app.state::<AppState>();
53→            *bridge_root.write().await = state.root_ipns_name.read().await.clone();
54→            *bridge_auth.write().await = *state.is_authenticated.read().await;
55→        }
56→    });
57→
58→    tokio::spawn(async move {
59→        let mut daemon = crate::sync::SyncDaemon::new(
60→            api,
61→            root_ipns_name_lock,
62→            is_authenticated_lock,
63→            rx,
64→            app_handle,
65→        );
66→        daemon.run().await;
67→    });
68→
69→    log::info!("Sync daemon spawned");
70→    Ok(())
71→}
